package fpv.render;
import arc.*;import arc.graphics.*;import arc.graphics.g2d.*;import arc.mock.*;import arc.util.*;import mindustry.*;import mindustry.content.*;import mindustry.core.*;import mindustry.game.*;import mindustry.gen.*;import mindustry.world.*;import mindustry.world.blocks.production.*;import mindustry.world.draw.*;import fpv.construction.*;import java.util.*;
/** Installed native crafters and separators; mock GL, not physical acceptance. */
public final class AdvancedManufacturingNativeTest {
 static int checks;static void check(boolean ok,String why){checks++;if(!ok)throw new AssertionError(why);}
 static class Tex extends Texture{Tex(){super();width=height=64;}}
 static void pose(Building b,float progress,float warm,float time){if(b instanceof GenericCrafter.GenericCrafterBuild c){c.progress=progress;c.warmup=warm;c.totalProgress=time;}else{var c=(Separator.SeparatorBuild)b;c.progress=progress;c.warmup=warm;c.totalProgress=time;}}
 static void regions(DrawBlock d,TextureRegion r){if(d instanceof DrawMulti m)for(var child:m.drawers)regions(child,r);if(d instanceof DrawFlame f)f.top=r;if(d instanceof DrawWeave w)w.weave=r;if(d instanceof DrawRegion region)region.region=r;}
 static DrawRegion spinner(DrawBlock d){if(d instanceof DrawRegion r&&"-spinner".equals(r.suffix))return r;if(d instanceof DrawMulti m)for(var child:m.drawers){var r=spinner(child);if(r!=null)return r;}return null;}
 static mindustry.type.ItemStack[] outputs(Block b){return b instanceof GenericCrafter c?c.outputItems:((Separator)b).results;}
 public static void main(String[] args)throws Exception{
        ArcNativesLoader.load();mindustry.graphics.CacheLayer.init();Core.app=new MockApplication();Core.files=new MockFiles();Core.settings=new MockSettings();Core.bundle=I18NBundle.createEmptyBundle();Core.audio=new MockAudio();Core.graphics=new MockGraphics();Core.gl=new MockGL20();Vars.headless=true;Vars.tree=new FileTree();Vars.content=new ContentLoader();Vars.content.createBaseContent();Vars.state=new GameState();Vars.net=new mindustry.net.Net(null);Groups.init();Vars.world=new World();Vars.world.tiles=new Tiles(128,96);Vars.world.setGenerating(true);Vars.world.tiles.fill();Vars.indexer=new mindustry.ai.BlockIndexer();Groups.resize(0,0,1024,768);Time.clear();Time.setDeltaProvider(()->1);Vars.content.init();Vars.state.set(GameState.State.playing);
        var pix=new Pixmap(32,32);pix.fill(0xa0a0a0ff);var region=new TextureAtlas.AtlasRegion(new Tex(),0,0,32,32);region.name="manufacturing-fixture";Core.atlas=new TextureAtlas(){@Override public PixmapRegion getPixmap(TextureAtlas.AtlasRegion a){return new PixmapRegion(pix);}};Core.atlas.addRegion("white",region);

  Block[] types={Blocks.kiln,Blocks.plastaniumCompressor,Blocks.phaseWeaver,Blocks.surgeSmelter,Blocks.separator,Blocks.disassembler};String[] names={"kiln","plastanium-compressor","phase-weaver","surge-smelter","separator","disassembler"};int[] sizes={2,2,2,3,2,3};
  check(!AdvancedManufacturingRenderer.supports(Blocks.graphitePress)&&!AdvancedManufacturingRenderer.supports(Blocks.massDriver)&&!AdvancedManufacturingRenderer.supports(Blocks.cryofluidMixer),"explicit six-block scope and prior models excluded");
  for(int i=0;i<types.length;i++){var type=types[i];check(type.name.equals(names[i])&&type.size==sizes[i],"actual installed name and footprint");check(i<4?type instanceof GenericCrafter:type instanceof Separator,"native separator class never replaced by crafter");type.region=type.fullIcon=region;regions(type instanceof GenericCrafter c?c.drawer:((Separator)type).drawer,region);System.out.println("A2-16e native "+type.name+" size="+type.size+" craftTime="+(type instanceof GenericCrafter c?c.craftTime:((Separator)type).craftTime)+" class="+type.getClass().getSimpleName());}
  check(((Separator)Blocks.separator).results.length==4&&((Separator)Blocks.disassembler).results.length==4,"real weighted-output definitions");
  check(spinner(((Separator)Blocks.separator).drawer).rotateSpeed==3&&spinner(((Separator)Blocks.disassembler).drawer).rotateSpeed==3,"installed native spinner speed matches presentation clock");
  var renderer=new AdvancedManufacturingRenderer();var batch=new NativeAtlasMesh.Builder(false);long id=100;
  try{
   for(var p:AdvancedManufacturingProfile.values())for(int lod=0;lod<3;lod++){
    int cells=types[p.ordinal()].size;var m=AdvancedManufacturingGeometry.model(p,cells,lod);check(m==AdvancedManufacturingGeometry.model(p,cells,lod),"immutable templates shared");int count=0;
    for(var a:new float[][]{m.body(),m.lining(),m.rotor(),m.slider(),m.rods(),m.energy()}){count+=a.length/8;check(a.length%24==0,"triangle stream");for(int i=0;i<a.length;i+=8){for(int j=0;j<8;j++)check(Float.isFinite(a[i+j]),"finite cached geometry");boolean rod=a==m.rods();check(Math.abs(a[i])<=(rod?1.001:.501)&&Math.abs(a[i+2])<=.501&&a[i+1]>=(a==m.rotor()&&p==AdvancedManufacturingProfile.DISASSEMBLER?-.16:0)&&a[i+1]<=1,"bounded local parts; normalized ram rods and pivot-centered drums explicit");check(a[i+6]<0||a[i+6]>=0&&a[i+6]<=1&&a[i+7]>=0&&a[i+7]<=1,"atlas-safe template UVs");}}
    check(count<3500&& (lod<2||count<=36),"bounded detailed/far geometry");
   }
   for(int floor:new int[]{0,1,3,4,5})for(int t=0;t<types.length;t++)for(int rotation=0;rotation<4;rotation++){
    var owner=new LayerBuildingAdapter(null);var b=AdvancedLogisticsNativeTest.put(owner,id++,12+rotation*24,10+t*12,floor,types[t],rotation);var p=AdvancedManufacturingProfile.forBlock(b.block);b.items.clear();b.enabled=true;b.efficiency=1;pose(b,.5f,1,21);if(b.liquids!=null)b.liquids.set(Liquids.slag,b.block.liquidCapacity*.5f);
    check(AdvancedManufacturingRenderer.activity(b)==1,"real native active state");float angle=AdvancedManufacturingRenderer.angle(b,p),shuttle=AdvancedManufacturingRenderer.shuttle(b);Time.time+=200;check(angle==AdvancedManufacturingRenderer.angle(b,p)&&shuttle==AdvancedManufacturingRenderer.shuttle(b),"global render time cannot advance machinery");pose(b,.5f,1,22);check(angle!=AdvancedManufacturingRenderer.angle(b,p),"native accumulated time drives articulation");
    if(p==AdvancedManufacturingProfile.COMPRESSOR){float stroke=AdvancedManufacturingRenderer.compression(b);check(Math.abs(stroke-.12f)<.00001,"native compression cycle");check(-.17f+stroke<=-.045f&&.13f+stroke>0,"ram stops at die and rod stays attached");}
    for(float distance:new float[]{0,900,10000}){
     var before=LogisticsModelNativeTest.state(b);float clock=b.totalProgress();batch.clear();float h=fpv.net.HeadlessGeometry.heightFor(b.block),base=floor*1.4f;check(renderer.render(b,batch,0,base,0,b.block.size,h,distance),"all native floors/rotations/LODs");var v=LogisticsModelNativeTest.vertices(batch);check(v.length>0,"mesh submitted");for(float value:v)check(Float.isFinite(value),"finite transformed stream");for(int i=0;i<v.length;i+=9){check(Math.abs(v[i])<=b.block.size*.501f&&Math.abs(v[i+2])<=b.block.size*.501f&&v[i+1]>=base-.0001f&&v[i+1]<=base+h+.005f,"animated geometry stays in actual unchanged footprint/height");check(v[i+7]>=0&&v[i+7]<=.5f&&v[i+8]>=0&&v[i+8]<=.5f,"all native/white UVs remain inside fixture atlas regions");}check(Arrays.equals(before,LogisticsModelNativeTest.state(b))&&clock==b.totalProgress(),"render cannot mutate resources/progress/warmup/RNG seed/native state");
    }
    b.enabled=false;check(AdvancedManufacturingRenderer.activity(b)==0,"disabled machinery rests");b.enabled=true;b.efficiency=0;check(AdvancedManufacturingRenderer.activity(b)==0,"power/input interruption rests");b.efficiency=1;b.items.set(outputs(b.block)[0].item,b.block.itemCapacity);check(AdvancedManufacturingRenderer.activity(b)==0,"output-capacity stop honored by native type");
   }
   var owner=new LayerBuildingAdapter(null);for(int t=0;t<types.length;t++){
    var b=owner.create(id++,12+t*5,86,3,types[t],Team.sharded,0);b.items.clear();for(var c:b.block.consumers)if(c instanceof mindustry.world.consumers.ConsumeItems items)for(var stack:items.items)b.items.set(stack.item,Math.min(b.block.itemCapacity,stack.amount*3));if(b.liquids!=null){b.liquids.set(Liquids.slag,100);b.liquids.set(Liquids.oil,100);}if(b.power!=null)b.power.status=1;b.enabled=true;b.efficiency=1;pose(b,0,0,0);
    boolean produced=false;for(int tick=0;tick<250&&!produced;tick++){Time.delta=1;b.updateTile();for(var output:outputs(b.block))produced|=b.items.get(output.item)>0;}check(produced,"installed native implementation produces "+b.block.name);byte[] before=LogisticsModelNativeTest.state(b);float clock=b.totalProgress();long builds=renderer.builds();for(int frame=0;frame<25;frame++){batch.clear();renderer.render(b,batch,0,4.2f,0,b.block.size,fpv.net.HeadlessGeometry.heightFor(b.block),0);}check(Arrays.equals(before,LogisticsModelNativeTest.state(b))&&clock==b.totalProgress(),"repeated rendering cannot craft, consume, advance RNG or duplicate resources");check(renderer.builds()==builds,"no instance/frame/state regeneration");
   }
   check(renderer.entries()==6&&renderer.builds()==6&&renderer.bytes()<2_000_000,"one bounded shared cache per type");System.out.println("AdvancedManufacturingNativeTest: "+checks+" native definitions/geometry/UV/animation/LOD/XYZ/read-only/RNG/output/cache checks PASS; mock GL, physical acceptance separate");
  }finally{renderer.clear();batch.dispose();pix.dispose();}
 }
}
